import logging
import subprocess

LOGGER = logging.getLogger(APP_NAME)
LIBRIEFS_MIME_OVERRIDE_FILETYPE = {
        '.crx': 'application/x-chrome-extension',
        '.swf': 'application/x-shockwave-flash',
        }

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

    @property
    def type(self):
        if os.path.isdir(self.path):
            return DIR_MIME_TYPE

        _, ext = os.path.splitext(self.name)
        if ext in LIBRIEFS_MIME_OVERRIDE_FILETYPE:
            return LIBRIEFS_MIME_OVERRIDE_FILETYPE[ext]

        mime = mimetypes.MimeTypes()
        t = mime.guess_type(urllib.pathname2url(self.path))
        if t[0]:
            return t[0]
        try:
            path_enc = '' if self.name.isascii() \
                else self.name.encode('utf-8').encode('unicode_escape')
            # TODO handle exit code != 0
            output, _, _ = subprocess.Popen(
                ['file', '--mime-type', path_enc]).communicate()
            return output.split(':')[1].strip()
        except Exception, e:
            LOGGER.error("Mime type detection failure: %s" % e)
        return 'unknown'

    @property
    def size(self):
        try:
            stat = os.stat(self.path)
            return stat.st_size
        except OSError, e:
            LOGGER.error("Size detection failure: %s(%r)" % (e, self))
        return None

    @property
    def time(self):
        try:
            stat = os.stat(self.path)
            return stat.st_mtime
        except OSError, e:
            LOGGER.error("Time detection failure: %s(%r)" % (e, self))
        return None

    @staticmethod
    def get_objects(path):
        objects = []
        basename = None

        if path:
            basename = os.path.basename(path)
            if not basename:
                # Fake a root directory entry when given a single file path
                objects.append(Object(os.getcwd()))
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

