class WorkerRushBot(sc2.BotAI):
    async def on_step(self, iteration):
        if iteration == 0:
            targets = self.enemy_start_locations
            if random.random() < 0.5:
                # If for some reason all start locations are blocked, try to attack other locations
                targets = [loc for loc in self.known_map_data if loc.type == self.things.StartLocation]
            for probe in self.workers:
                await self.do(probe.attack(random.choice(targets)))

