import os
import urllib
import mimetypes
import logging
import re

log = logging.getLogger(__name__)
file_magic = None

def get_file_mime_type(path):
    global file_magic

    if file_magic is None:
        try:
            import filemagic
        except ImportError:
            log.warning("filemagic is not available. Install python-filemagic for better mime-type detection")

        file_magic = filemagic.Magic()

    mime = mimetypes.MimeTypes()
    guessed = mime.guess_type(urllib.pathname2url(path))[0]

    try:
        detected_file_type = file_magic.id_filename(path)

        # This isn't perfect; some "text" files may be encoded as UTF-8 or UTF-16
        if detected_file_type.startswith("ASCII"):
            return "text/plain"
        elif detected_file_type.startswith("Unicode text"):
            return "text/plain"
        elif detected_file_type.startswith("JPEG"):
            return "image/jpeg"
        elif detected_file_type.startswith("PNG"):
            return "image/png"
        elif detected_file_type.startswith("GIF"):
            return "image/gif"
        elif detected_file_type.startswith("PDF"):
            return "application/pdf"

        if guessed:
            return guessed
        else:
            return "application/octet-stream"
    except Exception:
        if guessed:
            return guessed
        else:
            return "application/octet-stream"

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            self.type = get_file_mime_type(self.path)

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

