def keystone_auth_filter_factory(global_config, **local_config):
    global_config.update(local_config)
    config_file_name = global_config.get('config_file')
    if not config_file_name:
        raise ValueError("No config file specified")
    config_file = ConfigParser.SafeConfigParser()
    try:
        readfilenames = config_file.read(config_file_name)
        if not readfilenames:
            raise ValueError("Cannot read config file: %s" % config_file_name)
        config = dict(config_file.items('keystone_authtoken'))
    except ConfigParser.ParsingError:
        raise ValueError("Cannot parse config file: %s" % config_file_name)
    except ConfigParser.NoSectionError:
        raise ValueError("There is no [keystone_authtoken] section in %s" % config_file_name)
    global_config.update(config)
    return auth_filter_factory(global_config)

